type Tab = "home" | "wallet" | "alerts" | "competitions" | "finance" | "account"
type Screen = "landing" | "language" | "country" | "auth" | "login" | "email-login" | "quick" | "forgot" | "verify" | "signup-name" | "signup-phone" | "signup-password" | "app"
type ModalType = "deposit" | "withdraw" | "transfer" | "settings" | "game" | "otc" | "trade" | null

const nav: { id: Tab; label: string; icon: typeof Home }[] = [
  { id: "account", label: "My Account", icon: User },
  { id: "wallet", label: "Wallet", icon: Wallet },
  { id: "alerts", label: "Notifications", icon: Bell },
  { id: "competitions", label: "Competitions", icon: Trophy },
  { id: "finance", label: "Finance", icon: ReceiptText },
  { id: "home", label: "Home", icon: Home },
]

export default function Page() {
  const [intro, setIntro] = useState(true)
  const [screen, setScreen] = useState<Screen>("language")
  const [language, setLanguage] = useState<"en" | "ar">("en")
  const [tab, setTab] = useState<Tab>("home")
  const [balance, setBalance] = useState(0)
  const [modal, setModal] = useState<ModalType>(null)
  const [toast, setToast] = useState("")
  const [code, setCode] = useState("")
  const [verificationPhone, setVerificationPhone] = useState("")
  const [verificationMode, setVerificationMode] = useState<"signup" | "quick">("quick")
  const [authError, setAuthError] = useState("")
  const [authLoading, setAuthLoading] = useState(false)
  const [darkMode, setDarkMode] = useState(true)
  const [account, setAccount] = useState<{ name: string; phone: string; email?: string; accountCode: string }>({ name: "Trivia Win User", phone: "", accountCode: "" })

  useEffect(() => {
    const savedLanguage = window.localStorage.getItem("trivia_win_language")
    if (savedLanguage === "ar" || savedLanguage === "en") setLanguage(savedLanguage)
    const savedAccount = window.localStorage.getItem("trivia_win_account")
    if (savedAccount) {
      try {
        const parsed = JSON.parse(savedAccount)
        setAccount({ name: parsed.name || "Trivia Win User", phone: parsed.phone || "", email: parsed.email || "", accountCode: parsed.accountCode || "" })
        const savedBalance = window.localStorage.getItem("trivia_win_balance")
        if (savedBalance) setBalance(Number(savedBalance) || 0)
      } catch { /* ignore malformed demo data */ }
    }
    const savedSession = window.localStorage.getItem("trivia_win_logged_in")
    if (savedSession === "true") {
      setIntro(false)
      setScreen("app")
      return
    }

  }, [])

  const finishIntro = useCallback(() => setIntro(false), [])
  const notify = (message: string) => { setToast(message); setTimeout(() => setToast(""), 2200) }

  if (intro) return <Splash onDone={finishIntro} />
  if (screen === "landing") return <Landing setScreen={setScreen} notify={notify} />
  if (screen === "language") return <LanguagePicker language={language} setLanguage={setLanguage} setScreen={setScreen} />
  if (screen === "country") return <CountryPicker language={language} setScreen={setScreen} />
  if (screen === "auth") return <Auth screen={screen} setScreen={setScreen} />
  if (screen === "login" || screen === "email-login" || screen === "quick" || screen === "signup-name" || screen === "signup-phone" || screen === "signup-password") return <AuthWithSupabase screen={screen} setScreen={setScreen} setCode={setCode} setBalance={setBalance} setVerificationPhone={setVerificationPhone} setVerificationMode={setVerificationMode} setAuthError={setAuthError} authError={authError} authLoading={authLoading} setAuthLoading={setAuthLoading} />
  if (screen === "forgot") return <Forgot setScreen={setScreen} />
  if (screen === "verify") return <Verify code={code} setCode={setCode} setScreen={setScreen} phone={verificationPhone} mode={verificationMode} setAuthError={setAuthError} setAuthLoading={setAuthLoading} authLoading={authLoading} />

  const displayName = account.name || "Trivia Win User"
  const initials = ""

  return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><div className="mx-auto min-h-screen w-full max-w-[520px] bg-[#09090a] pb-24">
    <header className={`flex items-center justify-between border-b px-4 py-4 ${darkMode ? "border-white/[.06]" : "border-black/[.08]"}`}><button onClick={() => setModal("settings")} aria-label="Open Settings" className="flex size-11 items-center justify-center rounded-2xl border border-white/10 bg-white/5 text-white transition hover:border-amber-400/60 hover:text-amber-300"><Settings className="size-5" /></button><div className="flex items-center gap-3"><div className="text-right"><p className="text-xs text-white/45">مرحباً</p><p className="font-black">{displayName}</p><p className="text-xs text-white/35">{account.phone || account.email || "حساب تجريبي"}</p><p className="text-xs font-bold text-amber-300">الكود: {account.accountCode || "سيظهر بعد التسجيل"}</p></div><span className="size-3 rounded-full bg-[#21ce61]" /></div></header>
    {tab === "home" ? <HomePanel balance={balance} setModal={setModal} notify={notify} /> : <Inner tab={tab} balance={balance} account={account} setTab={setTab} setModal={setModal} notify={notify} />}
  </div><BottomNav tab={tab} setTab={setTab} />{toast && <div className="fixed bottom-24 left-1/2 z-50 -translate-x-1/2 rounded-full bg-white px-5 py-3 text-sm font-bold text-black shadow-2xl">{toast}</div>}{modal && <ActionModal type={modal} balance={balance} setBalance={setBalance} close={() => setModal(null)} notify={notify} darkMode={darkMode} setDarkMode={setDarkMode} />}</main>
}

const SPLASH_STEPS = 5

function Splash({ onDone }: { onDone: () => void }) {
  const [step, setStep] = useState(0)

  useEffect(() => {
    if (step >= SPLASH_STEPS) {
      const finish = setTimeout(onDone, 600)
      return () => clearTimeout(finish)
    }
    const next = setTimeout(() => setStep((value) => value + 1), step === 0 ? 500 : 750)
    return () => clearTimeout(next)
  }, [step, onDone])

  const reveal = (from: number) => `transition-all duration-700 ${step >= from ? "translate-y-0 opacity-100" : "translate-y-3 opacity-0"}`

  return (
    <main dir="ltr" className="flex min-h-screen items-center justify-center bg-[#080809] text-white">
      <section className="flex min-h-screen w-full max-w-[520px] flex-col items-center justify-center px-6 text-center">
        <div className="mb-24 flex size-28 flex-col items-center justify-center rounded-full border-[6px] border-[#1386d0] text-[#ff7b13] shadow-[0_0_30px_rgba(19,134,208,.2)]">
          <b className="text-7xl leading-none">?</b>
          <span className="text-sm font-black text-[#1386d0]">TRIVIA WIN</span>
        </div>
        <h1 className={`text-4xl font-black ${reveal(1)}`}>Trivia Win</h1>
        <p className={`mt-3 text-xl text-white/45 ${reveal(2)}`}>Play &amp; Win</p>
        <div className="mt-14 min-h-20 text-xl text-white/50">
          <p className={reveal(3)}>&quot;Success is not the end of the road,</p>
          <p className={`mt-1 ${reveal(4)}`}>failure is not fatal&quot;</p>
        </div>
        <div className="mt-16 flex items-center gap-5" role="progressbar" aria-label="Loading" aria-valuemin={0} aria-valuemax={SPLASH_STEPS} aria-valuenow={Math.min(step, SPLASH_STEPS)}>
          {Array.from({ length: SPLASH_STEPS }).map((_, index) => {
            const done = step > index
            const current = step === index
            return (
              <i
                key={index}
                className={`rounded-full transition-all duration-500 ${done ? "size-4 bg-[#ffc329] shadow-[0_0_22px_#ffc329]" : current ? "size-4 border-2 border-[#816d2e]" : "size-4 border-2 border-white/20"}`}
              />
            )
          })}
        </div>
        <b className="mt-14 text-[#d8ac18]">v1.9.3</b>
      </section>
    </main>
  )
}

function Landing({ setScreen, notify }: { setScreen: (s: Screen) => void; notify: (m: string) => void }) { return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><section className="mx-auto flex min-h-screen w-full max-w-[520px] flex-col items-center px-6 py-7 text-center"><button onClick={() => notify("Theme toggled")} aria-label="Toggle Theme" className="self-start rounded-full p-2 text-xl text-white/45">☼</button><div className="mt-8 flex size-28 flex-col items-center justify-center rounded-full border-[6px] border-[#1386d0] text-[#ff7b13] shadow-[0_0_24px_rgba(19,134,208,.16)]"><b className="text-7xl leading-none">?</b><span className="text-sm font-black text-[#1386d0]">TRIVIA WIN</span></div><h1 className="mt-8 text-4xl font-black">Trivia Win</h1><h2 className="mt-3 text-2xl font-black">العب واكسب</h2><p className="mt-2 text-sm text-white/45">اختبر معلوماتك واربح جوائز حقيقية</p><div className="mt-10 grid w-full grid-cols-3 divide-x divide-white/10 rounded-2xl bg-[#151516] px-3 py-4"><div><b className="text-2xl text-white">20</b><p className="text-xs text-white/45">سؤالاً</p></div><div><b className="text-2xl text-[#ff9d18]">10s</b><p className="text-xs text-white/45">لكل سؤال</p></div><div><b className="text-2xl text-[#20ca5d]">1500</b><p className="text-xs text-white/45">جائزة</p></div></div><div className="mt-7 w-full rounded-2xl border border-white/[.08] bg-[#151516] px-4 py-3 text-sm text-white/50"><p>نظام دفع آلي ومؤمن 100%</p><div className="mt-2 flex justify-center gap-5 text-xs"><span><i className="mr-1 inline-block size-2 rounded-full bg-[#20ca5d]"/>إيداع فوري</span><span><i className="mr-1 inline-block size-2 rounded-full bg-[#d89b20]"/>سحب آلي</span></div></div><div className="mt-auto flex w-full flex-col gap-3 pt-7"><button onClick={() => setScreen("language")} className="rounded-2xl bg-[#ff9d18] py-4 text-lg font-black text-black shadow-[0_8px_28px_rgba(255,157,24,.16)]">انشاء حساب جديد</button><button onClick={() => setScreen("language")} className="rounded-2xl border border-white/10 py-4 font-bold text-white/80">عندي حساب</button></div></section></main> }

const supportedLanguages = [{ code: "en", label: "English", native: "English", active: true }, { code: "ar", label: "Arabic", native: "العربية", active: true }, { code: "es", label: "Spanish", native: "Español", active: false }, { code: "fr", label: "French", native: "Français", active: false }, { code: "de", label: "German", native: "Deutsch", active: false }, { code: "it", label: "Italian", native: "Italiano", active: false }, { code: "pt", label: "Portuguese", native: "Português", active: false }, { code: "tr", label: "Turkish", native: "Türkçe", active: false }, { code: "ru", label: "Russian", native: "Русский", active: false }, { code: "zh", label: "Chinese", native: "中文", active: false }, { code: "ja", label: "Japanese", native: "日本語", active: false }, { code: "ko", label: "Korean", native: "한국어", active: false }]
const countries = ["Egypt", "Afghanistan", "Albania", "Algeria", "Argentina", "Australia", "Austria", "Bahrain", "Bangladesh", "Belgium", "Brazil", "Canada", "China", "Colombia", "Croatia", "Cyprus", "Denmark", "Finland", "France", "Germany", "Greece", "India", "Indonesia", "Iraq", "Ireland", "Italy", "Japan", "Jordan", "Kuwait", "Lebanon", "Libya", "Malaysia", "Mexico", "Morocco", "Netherlands", "New Zealand", "Nigeria", "Norway", "Oman", "Pakistan", "Palestine", "Philippines", "Poland", "Portugal", "Qatar", "Romania", "Russia", "Saudi Arabia", "Singapore", "South Africa", "South Korea", "Spain", "Sudan", "Sweden", "Switzerland", "Syria", "Tunisia", "Turkey", "UAE", "Ukraine", "United Kingdom", "United States", "Yemen"]

function PickerShell({ children, title, subtitle, onBack, arabic = false }: { children: ReactNode; title: string; subtitle: string; onBack: () => void; arabic?: boolean }) { return <main dir={arabic ? "rtl" : "ltr"} className="min-h-screen bg-[#080809] text-white"><section className="mx-auto min-h-screen w-full max-w-[520px] px-6 py-8"><button onClick={onBack} className="rounded-full border border-white/10 px-4 py-2 text-white/60">Back</button><div className="mt-16 text-center"><div className="mx-auto flex size-16 items-center justify-center rounded-2xl bg-[#ff9d18] text-3xl font-black text-black">?</div><h1 className="mt-7 text-3xl font-black">{title}</h1><p className="mt-3 text-white/45">{subtitle}</p></div>{children}</section></main> }
function LanguagePicker({ language: selectedLanguage, setLanguage, setScreen }: { language: "en" | "ar"; setLanguage: (language: "en" | "ar") => void; setScreen: (s: Screen) => void }) { const isArabic = selectedLanguage === "ar"; return <PickerShell title={isArabic ? "اختر اللغة" : "Choose your language"} subtitle={isArabic ? "اختر لغة التطبيق للمتابعة" : "Select your app language to continue"} arabic={isArabic} onBack={() => setScreen("landing")}><div className="mt-8 grid gap-3">{supportedLanguages.map(language => <button key={language.code} disabled={!language.active} onClick={() => { if (language.code === "en" || language.code === "ar") { setLanguage(language.code); window.localStorage.setItem("trivia_win_language", language.code); setScreen("country") } }} className={`flex items-center justify-between rounded-2xl border p-4 text-left transition ${language.active ? "border-white/10 bg-[#151516] hover:border-[#ff9d18]" : "cursor-not-allowed border-white/5 bg-white/[.03] opacity-45"}`}><span><b className="block">{language.label}</b><small className="text-white/45">{language.native}</small></span><span className={`text-xs font-bold ${language.active ? "text-emerald-400" : "text-white/35"}`}>{language.active ? "Available" : "Coming soon"}</span></button>)}</div></PickerShell> }
function CountryPicker({ language, setScreen }: { language: "en" | "ar"; setScreen: (s: Screen) => void }) { const isArabic = language === "ar"; return <PickerShell title={isArabic ? "اختر بلدك" : "Choose your country"} subtitle={isArabic ? "اختر بلدك لتخصيص حسابك" : "Select your country to personalize your account"} arabic={isArabic} onBack={() => setScreen("language")}><div className="mt-8 grid max-h-[52vh] gap-2 overflow-y-auto pr-1">{countries.map(country => <button key={country} onClick={() => setScreen("auth")} className="flex items-center justify-between rounded-2xl border border-white/10 bg-[#151516] p-4 text-left transition hover:border-[#ff9d18]"><span>{country}</span><span className="text-white/30">›</span></button>)}</div></PickerShell> }

function Auth({ screen, setScreen }: { screen: Screen; setScreen: (s: Screen) => void }) { const login = screen === "login"; return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><section className="mx-auto flex min-h-screen w-full max-w-[520px] flex-col px-6 py-8"><button onClick={() => setScreen("landing")} className="self-start rounded-full border border-white/10 px-4 py-2 text-white/60">Back</button><div className="mt-20 text-center"><h1 className="text-3xl font-black">{login ? "Login" : screen === "quick" ? "Quick Login" : "اختر طريقة التسجيل"}</h1><p className="mt-3 text-white/45">{login ? "ادخل إلى حسابك واستكمل اللعب" : "اختر الطريقة الأنسب لك"}</p></div>{login ? <div className="mt-10 flex flex-col gap-4"><input aria-label="رقم الهاتف أو Email" placeholder="رقم الهاتف أو Email" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><input aria-label="Password" type="password" placeholder="Password" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={() => setScreen("app")} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">دخول</button><button onClick={() => setScreen("quick")} className="py-3 text-white/50">Quick Login بدون كلمة مرور</button><button onClick={() => setScreen("forgot")} className="py-2 text-sm text-[#ffb31c]">نسيت Password؟</button></div> : <div className="mt-10 flex flex-col gap-4"><button onClick={() => setScreen(screen === "quick" ? "verify" : "signup-name")} className="rounded-2xl bg-[#ff9d18] p-5 text-right"><b className="block text-xl">{screen === "quick" ? "إرسال ��مز الدخول" : "التسجيل السريع"}</b><span className="text-sm text-black/60">بدون بريد إلكتروني، في ثوانٍ</span></button>{screen !== "quick" && <button onClick={() => setScreen("email-login")} className="rounded-2xl bg-[#151516] p-5 text-right"><b className="block text-xl">التسجيل بالبريد</b><span className="text-sm text-white/40">استخدم بريدك الإلكتروني</span></button>}</div>}</section></main> }

function AuthWithSupabase({ screen, setScreen, setCode, setBalance, setVerificationPhone, setVerificationMode, setAuthError, authError, authLoading, setAuthLoading }: { screen: Screen; setScreen: (s: Screen) => void; setCode: (value: string) => void; setBalance: (value: number) => void; setVerificationPhone: (value: string) => void; setVerificationMode: (value: "signup" | "quick") => void; setAuthError: (value: string) => void; authError: string; authLoading: boolean; setAuthLoading: (value: boolean) => void }) {
  const signup = screen === "auth" || screen === "signup-name" || screen === "signup-phone" || screen === "signup-password"
  const login = screen === "login"
  const emailLogin = screen === "email-login"
  const [email, setEmail] = useState("")
  const [phone, setPhone] = useState("")
  const [name, setName] = useState("")
  const [password, setPassword] = useState("")

  const normalizedPhone = phone.replace(/\D/g, "")
  const validPhone = /^01\d{9}$/.test(normalizedPhone)

  const saveAccount = (account: { phone: string; email?: string; password?: string; name: string; accountCode?: string }) => {
    const accountWithCode = { ...account, accountCode: account.accountCode || `TW-${Math.random().toString(36).slice(2, 10).toUpperCase()}` }
    window.localStorage.setItem("trivia_win_account", JSON.stringify(accountWithCode))
    window.localStorage.setItem("trivia_win_logged_in", "true")
    const isAdmin = accountWithCode.phone === "01271114573"
    setBalance(isAdmin ? 100000 : 0)
    window.localStorage.setItem("trivia_win_balance", String(isAdmin ? 100000 : 0))
  }

  const nextSignupStep = () => {
    setAuthError("")
    if (!name.trim()) { setAuthError("Enter your full name to continue"); return }
    setScreen("signup-phone")
  }

  const nextPhoneStep = () => {
    setAuthError("")
    if (!validPhone) { setAuthError("Enter an 11-digit number starting with 01"); return }
    setScreen("signup-password")
  }

  const finishSignup = () => {
    setAuthError("")
    if (!password.trim()) { setAuthError("Enter your password to continue"); return }
    saveAccount({ phone: normalizedPhone, password, name: name.trim() })
    setScreen("app")
  }

  const loginWithPhone = () => {
    setAuthError("")
    if (!validPhone) { setAuthError("Enter an 11-digit number starting with 01"); return }
    if (!password.trim()) { setAuthError("Enter your password to continue"); return }
    const saved = window.localStorage.getItem("trivia_win_account")
    const account = saved ? JSON.parse(saved) : { phone: normalizedPhone, name: "Trivia Win User" }
    saveAccount({ ...account, phone: normalizedPhone, password })
    setScreen("app")
  }

  const quickLogin = () => {
    setAuthError("")
    if (!validPhone) { setAuthError("ا��تب رقمًا يبدأ بـ 01 ويتكون من 11 رقمًا"); return }
    setVerificationPhone(normalizedPhone)
    setVerificationMode("quick")
    setCode("")
    setScreen("verify")
  }

  const emailLoginSubmit = () => {
    if (!email.trim() || !password.trim()) { setAuthError("Enter your email and password to continue"); return }
    saveAccount({ phone: "", email: email.trim(), password, name: "Trivia Win User" })
    setScreen("app")
  }

  const title = signup ? (screen === "signup-phone" ? "Mobile Number" : screen === "signup-password" ? "كلمة ال��رور" : "Create New Account") : emailLogin ? "Login بالبريد" : login ? "Login" : "Quick Login"
  const subtitle = signup ? (screen === "signup-name" || screen === "auth" ? "Enter your full name to create your account" : screen === "signup-phone" ? "اكتب Mobile Number المصري بد��ن رمز الدولة" : "اختر كلمة مرور لحماية حسابك") : emailLogin ? "Separate email login interface" : login ? "ادخل إلى حسابك برقم الهاتف المصري" : "ادخل برقم هاتفك بدون كلمة مرور"

  return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><section className="mx-auto flex min-h-screen w-full max-w-[520px] flex-col px-6 py-8"><button onClick={() => setScreen(signup && screen !== "signup-name" ? (screen === "signup-password" ? "signup-phone" : "signup-name") : "landing")} className="self-start rounded-full border border-white/10 px-4 py-2 text-white/60">Back</button><div className="mt-20 text-center"><div className="mx-auto mb-7 flex size-20 items-center justify-center rounded-full border-4 border-[#1386d0] text-5xl font-black text-[#ff7b13]">?</div><h1 className="text-3xl font-black">{title}</h1><p className="mt-3 text-white/45">{subtitle}</p></div><div className="mt-10 flex flex-col gap-4">{signup && (screen === "auth" || screen === "signup-name") && <><input autoFocus aria-label="الاسم الثلاث����" value={name} onChange={e => setName(e.target.value)} placeholder="الاسم الثلاثي" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={nextSignupStep} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">التالي</button></>}{signup && screen === "signup-phone" && <><input autoFocus aria-label="Mobile Number" type="tel" inputMode="numeric" value={phone} onChange={e => setPhone(e.target.value.replace(/\D/g, "").slice(0, 11))} placeholder="رقم يبدأ بـ 01 - 11 رقمًا" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={nextPhoneStep} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">التالي</button></>}{signup && screen === "signup-password" && <><input autoFocus aria-label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={finishSignup} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">Create الحساب</button></>}{login && <><input aria-label="Mobile Number" type="tel" inputMode="numeric" value={phone} onChange={e => setPhone(e.target.value.replace(/\D/g, "").slice(0, 11))} placeholder="رقم يبدأ بـ 01 - 11 رقمًا" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><input aria-label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={loginWithPhone} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">دخول</button><button onClick={() => setScreen("quick")} className="py-3 text-white/50">Quick Login بدون كلمة مرور</button></>}{emailLogin && <><input aria-label="Email" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="Email" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><input aria-label="Password" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="Password" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={emailLoginSubmit} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">دخول</button></>}{screen === "quick" && <><input aria-label="Mobile Number" type="tel" inputMode="numeric" value={phone} onChange={e => setPhone(e.target.value.replace(/\D/g, "").slice(0, 11))} placeholder="رقم يبدأ بـ 01 - 11 رقمًا" className="rounded-2xl border border-white/10 bg-[#151516] p-4 outline-none"/><button onClick={quickLogin} className="rounded-2xl bg-[#ff9d18] py-4 font-black text-black">Quick Login</button></>}{authError && <p role="alert" className="rounded-2xl bg-[#42171a] p-4 text-center text-[#ff858a]">{authError}</p>}<div className="flex justify-center gap-4 text-sm text-white/45">{signup ? <button onClick={() => setScreen("login")}>لدي حساب بالفعل</button> : <button onClick={() => setScreen("signup-name")}>Create New Account</button>}{!signup && <button onClick={() => setScreen("email-login")}>الدخول بالبريد</button>}</div></div></section></main>
}

function Verify({ code, setCode, setScreen, phone, mode, setAuthError, setAuthLoading, authLoading }: { code: string; setCode: (v: string) => void; setScreen: (s: Screen) => void; phone: string; mode: "signup" | "quick"; setAuthError: (value: string) => void; setAuthLoading: (value: boolean) => void; authLoading: boolean }) {
  const [displayCode, setDisplayCode] = useState(() => String(Math.floor(100000 + Math.random() * 900000)))
  const [secondsLeft, setSecondsLeft] = useState(20)

  useEffect(() => {
    const timer = window.setInterval(() => {
      setSecondsLeft((seconds) => {
        if (seconds <= 1) {
          setDisplayCode(String(Math.floor(100000 + Math.random() * 900000)))
          setCode("")
          return 20
        }
        return seconds - 1
      })
    }, 1000)
    return () => window.clearInterval(timer)
  }, [setCode])

  const isValid = code.length === 6
  const confirmCode = async () => {
    setAuthError("")
    setAuthLoading(true)
    await new Promise((resolve) => setTimeout(resolve, 250))
    setAuthLoading(false)
    if (code !== displayCode) { setAuthError("رمز الدخول غير صحيح أو منتهي"); return }
    if (mode === "quick") {
      setScreen("signup-name")
      return
    }
    window.localStorage.setItem("trivia_win_logged_in", "true")
    setScreen("app")
  }

  return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><section className="mx-auto flex min-h-screen w-full max-w-[520px] flex-col px-6 py-8"><button onClick={() => setScreen("language")} className="self-start rounded-full border border-white/10 px-4 py-2 text-white/60">Back</button><div className="mt-24 rounded-[28px] border border-white/[.07] bg-[#151516] p-6 text-center"><h1 className="text-3xl font-black">{mode === "signup" ? "Confirm Create الحساب" : "Confirm Quick Login"}</h1><p className="mt-3 text-white/45">Enter the 6-digit code shown below to continue</p><div className="mx-auto mt-8 flex max-w-xs items-center justify-between rounded-2xl border border-[#ffb31c]/25 bg-[#201a0d] px-5 py-4"><b aria-label={`Current login code ${displayCode}`} className="flex items-center gap-2 text-4xl font-black tracking-[.18em] text-[#ffb31c]">{displayCode.split("").map((digit, index) => <span key={`${digit}-${index}`} className="min-w-7">{digit}</span>)}</b><span className="text-lg font-black text-[#ffb31c]" aria-live="polite">{secondsLeft}s</span></div><p className="mt-3 text-sm text-white/40" aria-live="polite">The code refreshes automatically every 20 seconds</p><input value={code} onChange={e => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))} inputMode="numeric" maxLength={6} aria-label="Verification code" placeholder="Enter 6 digits" className="mt-8 w-full rounded-2xl border border-white/10 bg-[#0b0b0c] p-4 text-center text-xl tracking-[.35em] outline-none focus:border-[#ff9d18]"/><button disabled={!isValid || authLoading} onClick={confirmCode} className="mt-4 w-full rounded-2xl bg-[#ff9d18] py-4 font-black text-black disabled:opacity-40">{authLoading ? "جارٍ التحقق..." : "Confirm رمز الدخول"}</button></div></section></main>
}

function HomePanel({ balance, setModal, notify }: { balance: number; setModal: (m: Exclude<ModalType, null>) => void; notify: (m: string) => void }) { return <><section className="border-b border-white/[.06] px-4 py-5"><div className="flex gap-3"><button onClick={() => setModal("withdraw")} className="flex flex-1 items-center justify-center gap-2 rounded-2xl border border-[#ef3941]/40 bg-[#321113] py-3 font-bold text-[#ff676d]"><ArrowDownLeft/>سحب</button><button onClick={() => setModal("deposit")} className="flex flex-1 items-center justify-center gap-2 rounded-2xl bg-[#20ca5d] py-3 font-bold"><Plus/>إيداع</button><div className="flex flex-1 items-center justify-center gap-2 rounded-2xl border border-[#8c5b06] bg-[#291f0c] text-[#ffc21c]"><CircleDollarSign/><span><small className="block text-xs text-white/45">الرصيد</small><b className="text-xl">{balance}</b></span></div></div></section><section className="px-5 pb-8 pt-16 text-center"><p className="text-2xl text-white/45">رصيدك</p><p className="mt-5 text-7xl font-black">{balance}</p><p className="mt-2 text-3xl text-white/45">عملة</p><p className="mt-5 text-xl text-white/45">ج.م <span className="text-[#20cf61]">{balance}</span></p><div className="mt-14 grid grid-cols-3 gap-4"><RoundAction icon={<ArrowDownLeft/>} label="سحب" tone="red" onClick={() => setModal("withdraw")}/><RoundAction icon={<RefreshCw/>} label="تحديث" tone="gray" onClick={() => notify("تم تحديث الرصيد")}/><RoundAction icon={<Plus/>} label="إيداع" tone="green" onClick={() => setModal("deposit")}/></div><div className="mt-10 text-right"><h2 className="text-2xl font-black">مسابقات Trivia Win</h2><p className="mt-1 text-sm text-white/45">اختر مسابقة واختبر معلوماتك</p><div className="mt-4 flex flex-col gap-3"><button onClick={() => setModal("game")} className="flex items-center justify-between rounded-2xl border border-emerald-500/25 bg-emerald-950/30 p-4 text-right"><span><b className="block text-lg">لعبة ��لأعلام</b><small className="text-white/45">20 سؤالاً · 10 ثوانٍ · الجائزة 1500</small></span><strong className="text-[#20ca5d]">1500 ← 500</strong></button><button onClick={() => notify("مسابقة التاريخ متاحة قريباً")} className="flex items-center justify-between rounded-2xl border border-violet-500/25 bg-violet-950/20 p-4 text-right"><span><b className="block text-lg">تحدي التاريخ</b><small className="text-white/45">20 سؤالاً تاريخياً صعباً</small></span><strong className="text-violet-300">1500 ← 500</strong></button><button onClick={() => notify("مسابقة الأفلام متاحة قريباً")} className="flex items-center justify-between rounded-2xl border border-rose-500/25 bg-rose-950/20 p-4 text-right"><span><b className="block text-lg">����سئلة الأفلام</b><small className="text-white/45">10 أسئلة أفلام صعبة</small></span><strong className="text-rose-300">750 ← 300</strong></button></div></div><div className="mt-16 rounded-[28px] bg-gradient-to-br from-[#ffb01b] to-[#ff7411] p-6 text-right"><p className="text-3xl font-black">العب واكسب</p><p className="mt-1">ادفع 500 عملة واربح 1500 عند الإجابة الصحيحة</p><button onClick={() => setModal("game")} className="mt-6 w-full rounded-2xl bg-white/25 py-4 text-lg font-black">ابدأ الآن ←</button></div></section></> }

function RoundAction({ icon, label, tone, onClick }: { icon: React.ReactNode; label: string; tone: "red" | "gray" | "green"; onClick: () => void }) { const style = tone === "green" ? "bg-[#20ca5d]" : tone === "red" ? "border-2 border-[#6c2429] bg-[#210d0f] text-[#fb4b52]" : "bg-[#222225] text-white/50"; return <button onClick={onClick} className="flex flex-col items-center gap-3 text-lg font-bold"><span className={`flex size-28 items-center justify-center rounded-full text-5xl ${style}`}>{icon}</span>{label}</button> }

function FinancePanel({ balance, setTab, setModal, notify }: { balance: number; setTab: (t: Tab) => void; setModal: (m: Exclude<ModalType, null>) => void; notify: (m: string) => void }) { const cards = [{ label: "تحويل", icon: "⇄", tone: "amber", iconClass: "text-[#ffc21c] bg-[#4c3108]", action: () => setModal("transfer") }, { label: "الإحالة", icon: "♧", tone: "pink", iconClass: "text-[#ff69b4] bg-[#42132f]", action: () => notify("شارك رابط الإحالة واحصل على مكافآت") }, { label: "النسخ", icon: "♧", tone: "purple", iconClass: "text-[#c27cff] bg-[#321751]", action: () => notify("خدمة النسخ متاحة الآن") }, { label: "تداول", icon: "↗", tone: "green", iconClass: "text-[#3ee49a] bg-[#064d36]", action: () => setModal("trade") }, { label: "السجل", icon: "◷", tone: "blue", iconClass: "text-[#70a5ff] bg-[#132d5d]", action: () => notify("لا توجد معاملات بعد") }]; return <section className="px-5 pb-8 pt-10"><div className="flex items-start justify-between"><div><p className="text-sm text-white/40">Trivia Win</p><h1 className="mt-2 text-4xl font-black">الخدمات Finance</h1><p className="mt-2 text-lg text-white/45">إدارة رصيدك وتحويلاتك</p></div><div className="flex size-20 items-center justify-center rounded-3xl border border-amber-500/40 bg-[#241b0c] text-5xl text-amber-400">▣</div></div><div className="mt-9 grid grid-cols-2 gap-4"><button onClick={() => setTab("wallet")} className="rounded-[28px] border border-emerald-500/40 bg-[#062b1c] p-6 text-right"><p className="text-lg text-white/50">Wallet Home</p><b className="mt-2 block text-5xl text-emerald-400">{balance}</b><span className="mt-4 block text-sm text-white/50">Wallet والسحب</span></button><button onClick={() => notify("رصيد الإحالة: 0 عملة")} className="rounded-[28px] border border-purple-500/40 bg-[#1b1028] p-6 text-right"><p className="text-lg text-white/50">رصيد الإحالة</p><b className="mt-2 block text-5xl text-purple-400">0</b><span className="mt-4 block text-sm text-white/50">دعوة الأصدقاء</span></button></div><div className="mt-8 grid grid-cols-5 gap-2">{cards.map(card => <button key={card.label} onClick={card.action} className={`rounded-[24px] border p-3 text-center transition-transform active:scale-95 ${card.tone === "amber" ? "border-[#70500c] bg-[#241b0c]" : card.tone === "pink" ? "border-[#70234f] bg-[#281022]" : card.tone === "purple" ? "border-[#57247a] bg-[#1e122c]" : card.tone === "green" ? "border-[#087148] bg-[#082b21]" : "border-[#1f4885] bg-[#101e3a]"}`}><span className={`mx-auto flex size-14 items-center justify-center rounded-2xl text-3xl ${card.iconClass}`}>{card.icon}</span><b className="mt-3 block text-sm">{card.label}</b>{card.label === "تداول" && <small className="mt-1 block rounded-full bg-red-500 text-[9px]">LIVE</small>}</button>)}</div><button onClick={() => setModal("otc")} className="mt-8 flex w-full items-center justify-between rounded-[28px] border border-indigo-500/50 bg-gradient-to-l from-[#102b37] to-[#12152b] p-6 text-right"><span><b className="text-2xl">Stocks OTC</b><small className="mt-2 block text-white/45">تداول الأسهم خارج البورصة - اشترِ وبِع الأسهم</small></span><span className="flex size-16 items-center justify-center rounded-2xl bg-[#1f347e] text-5xl text-indigo-300">▤</span></button><div className="mt-10 flex items-center justify-between"><h2 className="text-3xl font-black">آخر المعاملات</h2><button onClick={() => notify("لا توجد معاملات بعد")} className="text-xl text-amber-400">عرض الكل</button></div><div className="mt-5 rounded-3xl border border-white/10 bg-[#151516] p-7 text-center text-white/40">لا توجد معاملات حتى ال��ن</div></section> }

function Inner({ tab, balance, account, setTab, setModal, notify }: { tab: Tab; balance: number; account: { name: string; phone: string; email?: string; accountCode: string }; setTab: (t: Tab) => void; setModal: (m: Exclude<ModalType, null>) => void; notify: (m: string) => void }) { if (String(tab) === "account") return <section className="px-5 pt-10"><h1 className="text-4xl font-black">My Account</h1><div className="mt-7 space-y-3"><div className="rounded-3xl border border-white/10 bg-[#151516] p-6"><p className="text-white/45">عدد العملات الموجودة</p><b className="mt-2 block text-5xl text-amber-300">{balance}</b><span className="text-sm text-white/45">عملة</span></div><div className="flex items-center justify-between rounded-3xl border border-white/10 bg-[#151516] p-5"><span className="text-white/45">رقم إصدار التطبيق</span><b className="text-lg text-white">v1.0.0</b></div><button onClick={() => { window.localStorage.removeItem("trivia_win_logged_in"); window.location.reload() }} className="flex w-full items-center justify-center gap-3 rounded-3xl border border-red-500/30 bg-red-950/40 py-5 text-lg font-black text-red-300"><LogOut className="size-6" />تسجيل الخروج</button></div></section>; if (String(tab) === "finance") return <FinancePanel balance={balance} setTab={setTab} setModal={setModal} notify={notify} />; if (String(tab) === "wallet") return <section className="px-5 pt-10"><button onClick={() => setTab("home")} className="mb-5 flex items-center gap-1 text-white/45"><ChevronLeft/>Home</button><h1 className="text-4xl font-black">Wallet</h1><p className="mt-2 text-white/45">تحكم في رصيدك ومعاملاتك بسهولة</p><div className="mt-8 rounded-3xl border border-emerald-500/30 bg-emerald-950/30 p-6"><p className="text-white/50">الرصيد المتاح</p><b className="mt-2 block text-5xl text-emerald-400">{balance}</b><div className="mt-6 flex gap-3"><button onClick={() => setModal("deposit")} className="flex-1 rounded-2xl bg-emerald-500 py-3 font-black text-black">إيداع</button><button onClick={() => setModal("withdraw")} className="flex-1 rounded-2xl bg-red-500 py-3 font-black">سحب</button></div></div></section>; if (String(tab) === "alerts") return <section className="px-5 pt-10"><button onClick={() => setTab("home")} className="mb-5 flex items-center gap-1 text-white/45"><ChevronLeft/>Home</button><h1 className="text-4xl font-black">Notifications</h1><div className="mt-8 rounded-3xl border border-white/10 bg-[#151516] p-6"><Bell className="text-[#ffb31c]"/><p className="mt-4 text-xl font-bold">لا توجد إشعارات جديدة</p><p className="mt-2 text-white/45">سنخبرك بكل جديد في حسابك ومسابقاتك.</p></div></section>; if (String(tab) === "competitions") return <section className="px-5 pt-10"><button onClick={() => setTab("home")} className="mb-5 flex items-center gap-1 text-white/45"><ChevronLeft/>Home</button><h1 className="text-4xl font-black">Competitions</h1><p className="mt-2 text-white/45">اختر مسابقة واختبر معلو��اتك</p><button onClick={() => setModal("game")} className="mt-8 w-full rounded-3xl bg-gradient-to-br from-[#ffb01b] to-[#ff7411] p-7 text-right"><Trophy className="size-12"/><b className="mt-5 block text-2xl">لعبة الأعلام</b><span>20 سؤالاً · 10 ثوانٍ لكل سؤال</span></button></section>; const data: Record<Tab, [string,string]> = { wallet: ["Wallet","تحكم في رصيدك ومعاملاتك بسهولة"], alerts: ["Notifications","تابع أحدث أخبار حسابك ومسابقاتك"], competitions: ["Competitions","��ختبر معلوماتك واربح جوائز حقيقية"], finance: ["Finance و النسخ","راجع حركاتك Finance وتقارير الحساب"], account: ["My Account","إدارة بياناتك وإعدادات حسابك"], home: ["Home",""] }; const [title, subtitle] = data[tab]; return <section className="px-5 pt-10"><button onClick={() => setTab("home")} className="mb-5 flex items-center gap-1 text-white/45"><ChevronLeft/>Home</button><p className="text-sm text-white/40">Trivia Win</p><h1 className="mt-2 text-4xl font-black">{title}</h1><p className="mt-2 text-white/45">{subtitle}</p><div className="mt-7 rounded-[28px] border border-white/[.07] bg-[#151516] p-5">{tab === "account" && <div className="space-y-4"><div className="flex items-center gap-4"><div className="flex size-16 items-center justify-center rounded-2xl bg-[#ed3039] text-3xl font-black">{account.name.trim().charAt(0) || "S"}</div><div><p className="text-2xl font-black">{account.name || "Trivia Win User"}</p><p className="mt-1 text-sm text-white/45">بيانات الحساب المحفوظة</p></div></div><Stat label="كود الحساب للتحويل" value={account.accountCode || "سيظهر بعد التسجيل"} /><Stat label="رقم الهاتف" value={account.phone || "غير مضاف"} /><Stat label="Email" value={account.email || "غير مضاف"} /></div>}{tab === "wallet" && <><div className="flex justify-between text-white/45"><span>الرصيد المتاح</span><Wallet className="text-[#ffbd22]"/></div><p className="mt-3 text-5xl font-black">{balance} <span className="text-xl text-white/40">ج.م</span></p><div className="mt-5 grid grid-cols-2 gap-3"><button onClick={() => setModal("deposit")} className="rounded-2xl bg-[#20ca5d] py-3 font-bold">+ إيداع</button><button onClick={() => setModal("withdraw")} className="rounded-2xl bg-[#321113] py-3 font-bold text-[#ff676d]">سحب</button></div></>}{tab === "alerts" && <div className="py-12 text-center"><Bell className="mx-auto size-16 text-white/20"/><p className="mt-5 text-xl font-bold">لا توجد إشعارات</p><p className="mt-2 text-sm text-white/40">ستظهر هنا تحديثات حسابك</p></div>}{tab === "competitions" && <><div className="flex items-center gap-4"><Trophy className="text-[#ffb31c]"/><div><p className="text-xl font-black">العب واكسب</p><p className="text-sm text-white/45">20 سؤالاً · 10 ثوانٍ لكل سؤال</p></div></div><button onClick={() => setModal("game")} className="mt-5 w-full rounded-2xl bg-[#ff9d18] py-4 font-black text-black">ابدأ المسابقة</button></>}{tab === "finance" && <div className="flex flex-col gap-5"><Stat label="إجمالي الإيداعات" value={`${balance} عملة`}/><Stat label="إجمالي السحوبات" value="0 جنيه"/><Stat label="عدد العمليات" value="0 عملية"/></div>}{tab === "account" && <div className="flex flex-col gap-3"><div className="flex items-center gap-4 rounded-2xl bg-white/[.04] p-4"><span className="flex size-12 items-center justify-center rounded-full bg-[#ed3039] text-xl font-black">م</span><div><b></b><p className="text-sm text-white/40"></p></div></div><button onClick={() => notify(" جاهزة للتعديل")} className="flex items-center justify-between rounded-2xl bg-white/[.04] p-4"><span></span><CircleDollarSign/></button><button onClick={() => notify("تم ")} className="flex items-center justify-between rounded-2xl bg-[#321113] p-4 text-[#ff676d]"><span></span><LogOut/></button></div>}</div></section> }

function Stat({ label, value }: { label: string; value: string }) { return <div className="flex justify-between border-b border-white/[.06] pb-4"><span className="text-white/50">{label}</span><b>{value}</b></div> }

function BottomNav({ tab, setTab }: { tab: Tab; setTab: (t: Tab) => void }) { return <nav className="fixed bottom-0 left-1/2 z-20 flex w-full max-w-[520px] -translate-x-1/2 justify-between border-t border-white/[.08] bg-[#101011]/95 px-2 py-3 backdrop-blur-xl">{nav.map(({ id, label, icon: Icon }) => <button key={id} onClick={() => setTab(id)} className={`flex min-w-0 flex-1 flex-col items-center gap-1 text-[10px] font-bold ${tab === id ? "text-[#ff3e47]" : "text-white/45"}`}><Icon className="size-6"/><span>{label}</span></button>)}</nav> }

function SettingsScreen({ close, notify, darkMode, setDarkMode }: { close: () => void; notify: (m: string) => void; darkMode: boolean; setDarkMode: (value: boolean) => void }) { return <main dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#080809] text-white"><section className="mx-auto min-h-full w-full max-w-[520px] p-5"><header className="flex items-center justify-between border-b border-white/10 pb-5"><button onClick={close} aria-label="إغلاق Settings" className="text-4xl text-white/50">×</button><h1 className="text-3xl font-black">Settings</h1><Settings className="text-amber-300" /></header><div className="mt-7 space-y-3"><button onClick={() => { setDarkMode(!darkMode); notify(!darkMode ? "تم تفعيل المظهر الداكن" : "تم تفعيل المظهر الفاتح") }} className="flex w-full items-center justify-between rounded-3xl border border-white/10 bg-[#151516] p-5 text-right"><span><b className="block text-lg">المظهر</b><small className="text-white/45">التبديل بين الوضع الداكن والفاتح</small></span><span className="font-bold text-amber-300">{darkMode ? "داكن" : "فاتح"}</span></button><button onClick={() => notify("Notifications مفعلة")} className="flex w-full items-center justify-between rounded-3xl border border-white/10 bg-[#151516] p-5 text-right"><span><b className="block text-lg">Notifications</b><small className="text-white/45">تنبيهات Competitions وحركة الحساب</small></span><span className="rounded-full bg-emerald-500 px-3 py-1 text-xs font-bold text-black">مفعلة</span></button><div className="rounded-3xl border border-white/10 bg-[#151516] p-5"><p className="text-lg font-bold">عن التطبيق</p><p className="mt-2 text-sm text-white/45">Trivia Win · الإصدار v1.0.0</p></div></div></section></main> }

function RemovedCircleDollarSignScreen({ close, notify, darkMode, setDarkMode }: { close: () => void; notify: (m: string) => void; darkMode: boolean; setDarkMode: (value: boolean) => void }) { const [notifications, setNotifications] = useState(true); const [sound, setSound] = useState(true); return <main dir="ltr" className={`fixed inset-0 z-40 overflow-y-auto ${darkMode ? "bg-[#080809] text-white" : "bg-[#f5f6fa] text-[#172033]"}`}><section className="mx-auto min-h-full w-full max-w-[520px] p-5"><header className="flex items-center justify-between border-b border-white/10 pb-5"><button onClick={close} className="text-4xl text-white/50">��</button><h1 className="text-3xl font-black"></h1><CircleDollarSign className="text-[#ffb31c]"/></header><div className="mt-7 space-y-3"><button onClick={() => setNotifications(!notifications)} className="flex w-full items-center justify-between rounded-2xl border border-white/10 bg-[#151516] p-5"><span><b className="block text-lg">Notifications</b><small className="text-white/45">تنبيهات Competitions وتحركات الحساب</small></span><span className={`rounded-full px-3 py-1 text-xs font-bold ${notifications ? "bg-emerald-500 text-black" : "bg-white/10 text-white/50"}`}>{notifications ? "مفعلة" : "متوقفة"}</span></button><button onClick={() => setSound(!sound)} className="flex w-full items-center justify-between rounded-2xl border border-white/10 bg-[#151516] p-5"><span><b className="block text-lg">الأصوات</b><small className="text-white/45">أصوات الإجابات والتنبيهات</small></span><span className={`rounded-full px-3 py-1 text-xs font-bold ${sound ? "bg-emerald-500 text-black" : "bg-white/10 text-white/50"}`}>{sound ? "مفعلة" : "متوقفة"}</span></button><button onClick={() => { setDarkMode(!darkMode); notify(!darkMode ? "تم تفعيل المظهر الداكن" : "تم تفعيل المظهر الفاتح") }} className={`flex w-full items-center justify-between rounded-2xl border p-5 ${darkMode ? "border-white/10 bg-[#151516]" : "border-black/10 bg-white text-black"}`}><span><b className="block text-lg">المظهر</b><small className={darkMode ? "text-white/45" : "text-black/45"}>تبديل مظهر التطبيق بين الداكن والفاتح</small></span><span className="font-bold text-[#ffb31c]">{darkMode ? "داكن" : "فاتح"}</span></button><button onClick={() => notify("تم حفظ إعدادات الخصوصية")} className="w-full rounded-2xl bg-[#ff9d18] py-4 font-black text-black">حفظ </button></div></section></main> }

function TransferScreen({ balance, setBalance, close, notify }: { balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void }) { const [recipient, setRecipient] = useState(""); const [amount, setAmount] = useState(""); const submit = () => { const value = Number(amount); if (!/^TW-[A-Z0-9]{8,12}$/.test(recipient.trim().toUpperCase())) return notify("اكتب كود حساب صحيح مثل TW-AB12CD34"); if (!Number.isInteger(value) || value <= 0) return notify("اكتب عدد عملات صحيح"); if (value > balance) return notify("رصيدك غير كافٍ للتحويل"); setBalance(balance - value); notify(`تم إرسال ${value} عملة إلى ${recipient.toUpperCase()}`); setRecipient(""); setAmount(""); }; return <main dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#080809] text-white"><section className="mx-auto min-h-full w-full max-w-[520px] p-5"><header className="flex items-center justify-between"><button onClick={close} className="text-4xl text-white/50">×</button><div className="text-right"><h1 className="text-3xl font-black">تحويل العملات</h1><p className="text-white/45">أرسل العملات باستخدام كود الحساب</p></div><span className="text-4xl text-amber-400">⇄</span></header><div className="mt-10 rounded-3xl border border-amber-500/30 bg-[#241b0c] p-6"><p className="text-sm text-white/50">الرصيد المتاح</p><b className="mt-2 block text-4xl text-amber-300">{balance} عملة</b></div><div className="mt-6 rounded-3xl border border-white/10 bg-[#151516] p-6"><label className="text-sm text-white/50">كود حساب المستلم</label><input value={recipient} onChange={event => setRecipient(event.target.value.toUpperCase())} placeholder="TW-AB12CD34" className="mt-2 w-full rounded-2xl border border-white/10 bg-[#0d0d0e] p-4 text-lg outline-none"/><label className="mt-5 block text-sm text-white/50">عدد العملات</label><input type="number" min="1" step="1" value={amount} onChange={event => setAmount(event.target.value)} placeholder="مثال: 100" className="mt-2 w-full rounded-2xl border border-white/10 bg-[#0d0d0e] p-4 text-lg outline-none"/><button onClick={submit} className="mt-6 w-full rounded-2xl bg-amber-400 py-4 font-black text-black">Confirm التحويل</button></div><p className="mt-5 text-center text-xs text-white/35">راجع كود المس��لم قبل الConfirm. التحويلات لا يمكن التراجع عنها.</p></section></main> }

function MarketScreen({ mode, balance, setBalance, close, notify }: { mode: "otc" | "trade"; balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void }) { const [query, setQuery] = useState(""); const [selected, setSelected] = useState("EGX30"); const [amount, setAmount] = useState("100"); const [side, setSide] = useState<"buy" | "sell">("buy"); const isOtc = mode === "otc"; const markets = isOtc ? [{ symbol: "EGX30", name: "مؤشر البورصة المصرية", price: "31,842.10", change: "+1.24%" }, { symbol: "COMI", name: "البنك التجاري الدولي", price: "82.45", change: "+2.18%" }, { symbol: "TMGH", name: "طلعت مصطفى", price: "59.80", change: "-0.64%" }, { symbol: "SWDY", name: "السويدي إليكتريك", price: "71.25", change: "+0.92%" }] : [{ symbol: "BTC/USDT", name: "Bitcoin", price: "67,420.00", change: "+3.42%" }, { symbol: "ETH/USDT", name: "Ethereum", price: "3,842.18", change: "+1.86%" }, { symbol: "EUR/USD", name: "Euro / US Dollar", price: "1.0842", change: "-0.21%" }, { symbol: "GOLD", name: "الذهب الفوري", price: "2,382.40", change: "+0.71%" }]; const active = markets.find(item => item.symbol === selected) ?? markets[0]; const submit = () => { const value = Number(amount); if (!value || value <= 0) return notify("أدخل مبلغًا صحيحًا"); if (side === "buy" && value > balance) return notify("الرصيد غير كافٍ لهذه العملية"); setBalance(side === "buy" ? balance - value : balance + value); notify(`تم تنفيذ أمر ${side === "buy" ? "شراء" : "بيع"} وهمي بقيمة ${value} عملة`); }; return <main dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#080a0d] text-white"><section className="mx-auto min-h-full w-full max-w-[520px] pb-8"><header className="sticky top-0 z-10 flex items-center justify-between border-b border-white/10 bg-[#0b0d11]/95 px-5 py-5 backdrop-blur"><button onClick={close} aria-label="إغلاق السوق" className="text-4xl text-white/55">×</button><div className="text-right"><h1 className="text-2xl font-black">{isOtc ? "Stocks OTC" : "التداول"}</h1><p className="text-xs text-white/40">حساب تجريبي · أسعار وهمية للتجربة</p></div><CandlestickChart className="text-indigo-300"/></header><div className="p-5"><div className="relative"><Search className="absolute right-4 top-4 size-5 text-white/35"/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="ابحث عن سهم أو عملة" className="w-full rounded-2xl border border-white/10 bg-[#151820] p-4 pr-12 outline-none"/></div><div className="mt-4 flex gap-2 overflow-x-auto pb-2">{markets.filter(item => `${item.symbol} ${item.name}`.toLowerCase().includes(query.toLowerCase())).map(item => <button key={item.symbol} onClick={() => setSelected(item.symbol)} className={`min-w-[145px] rounded-2xl border p-3 text-right ${selected === item.symbol ? "border-indigo-400 bg-indigo-950/50" : "border-white/10 bg-[#12151b]"}`}><b className="block">{item.symbol}</b><span className="text-xs text-white/50">{item.name}</span><strong className="mt-2 block">{item.price}</strong><small className={item.change.startsWith("+") ? "text-emerald-400" : "text-rose-400"}>{item.change}</small></button>)}</div><div className="mt-5 rounded-3xl border border-white/10 bg-[#11151b] p-5"><div className="flex items-start justify-between"><div><p className="text-sm text-white/45">{active.name}</p><h2 className="mt-2 text-4xl font-black">{active.price}</h2><span className="text-emerald-400">{active.change} اليوم</span></div><TrendingUp className="size-10 text-emerald-400"/></div><div className="mt-8 flex h-32 items-end gap-1 rounded-2xl bg-[#0b1016] p-4">{[35,55,42,70,48,82,64,92,72,88,78,98,76,90].map((height, index) => <span key={index} style={{ height: `${height}%` }} className={`flex-1 rounded-t ${index > 9 ? "bg-indigo-400" : "bg-indigo-700/70"}`}/>)}</div></div><div className="mt-5 rounded-3xl border border-white/10 bg-[#11151b] p-5"><div className="mb-4 flex rounded-xl bg-[#0b0e13] p-1"><button onClick={() => setSide("buy")} className={`flex-1 rounded-lg py-3 font-bold ${side === "buy" ? "bg-emerald-500 text-black" : "text-white/45"}`}>شراء</button><button onClick={() => setSide("sell")} className={`flex-1 rounded-lg py-3 font-bold ${side === "sell" ? "bg-rose-500 text-white" : "text-white/45"}`}>بيع</button></div><label className="text-sm text-white/45">قيمة الأمر بالعملة</label><input type="number" value={amount} onChange={e => setAmount(e.target.value)} className="mt-2 w-full rounded-2xl border border-white/10 bg-[#0b0e13] p-4 text-xl outline-none"/><div className="mt-4 flex justify-between text-sm text-white/45"><span>الرصيد المتاح</span><b className="text-white">{balance} عملة</b></div><button onClick={submit} className={`mt-5 flex w-full items-center justify-center gap-2 rounded-2xl py-4 font-black ${side === "buy" ? "bg-emerald-500 text-black" : "bg-rose-500"}`}>{side === "buy" ? <ArrowUpRight/> : <ArrowDownRight/>}{side === "buy" ? "تنفيذ شراء وهمي" : "تنفيذ بيع وهمي"}</button></div><p className="mt-5 text-center text-xs text-white/35">هذه محاكاة تعليمية. لا يوجد تداول أو استثمار حقيقي.</p></div></section></main> }

function ActionModal({ type, balance, setBalance, close, notify, darkMode, setDarkMode }: { type: Exclude<ModalType, null>; balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void; darkMode: boolean; setDarkMode: (value: boolean) => void }) { if (type === "settings") return <SettingsScreen close={close} notify={notify} darkMode={darkMode} setDarkMode={setDarkMode} />; if (type === "transfer") return <TransferScreen balance={balance} setBalance={setBalance} close={close} notify={notify} />; if (type === "otc" || type === "trade") return <MarketScreen mode={type} balance={balance} setBalance={setBalance} close={close} notify={notify} />; if (type === "deposit") return <DepositScreen balance={balance} setBalance={setBalance} close={close} notify={notify} />; if (type === "withdraw") return <WithdrawScreen balance={balance} setBalance={setBalance} close={close} notify={notify} />; return <GameScreen balance={balance} setBalance={setBalance} close={close} notify={notify} />; const title = type === "withdraw" ? "سحب الرصيد" : "العب واكسب"; return <div className="fixed inset-0 z-40 flex items-end justify-center bg-black/75 p-4"><div className="w-full max-w-[520px] rounded-[30px] border border-white/10 bg-[#181819] p-6"><button onClick={close} aria-label="إغلاق" className="float-left rounded-full bg-white/10 p-2"><X/></button><h2 className="text-3xl font-black">{title}</h2><p className="mt-2 text-white/45">{type === "game" ? "ادفع 250 عملة وابدأ المسابقة" : "أدخل المبلغ وبيانات الا��تلام"}</p>{type === "withdraw" ? <><input type="number" placeholder="المبلغ" className="mt-7 w-full rounded-2xl border border-white/10 bg-[#0c0c0d] p-4 outline-none"/><button onClick={() => { setBalance(Math.max(0, balance - 100)); notify("تم بدء السحب"); close() }} className="mt-4 w-full rounded-2xl bg-[#ef3941] py-4 font-black">Confirm السحب</button></> : <button onClick={() => { notify("تم بدء المسابقة"); close() }} className="mt-7 w-full rounded-2xl bg-[#ff9d18] py-4 font-black text-black">ابدأ اللعب</button>}</div></div> }

function WithdrawScreen({ balance, setBalance, close, notify }: { balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void }) { const [amount, setAmount] = useState(""); const [method, setMethod] = useState("Vodafone Cash"); const [destination, setDestination] = useState(""); return <main dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#f7f8fb] text-[#172033]"><section className="mx-auto min-h-full w-full max-w-[520px] pb-8"><header className="flex items-center justify-between border-b border-[#e1e4ea] bg-white px-5 py-5"><button onClick={close} aria-label="إغلاق السحب" className="text-4xl text-[#6d7582]">×</button><h1 className="text-4xl font-black">سحب</h1><div className="flex items-center gap-2"><button onClick={() => notify("تواصل معنا عبر الاستفسارات")} className="rounded-full bg-[#eef4ff] px-4 py-2 font-bold text-[#3478db]">استفسارات</button><button onClick={close} className="text-xl text-[#3478db]">Back</button></div></header><div className="p-5"><div className="rounded-3xl bg-white p-5 shadow-sm"><p className="text-[#697181]">الرصيد الم��اح</p><p className="mt-2 text-4xl font-black">{balance} <span className="text-lg font-normal">ج.م</span></p></div><div className="mt-5 rounded-3xl bg-white p-5 shadow-sm"><h2 className="text-xl font-black">بيانات السحب</h2><label className="mt-5 block text-sm font-bold">المبلغ</label><input value={amount} onChange={e => setAmount(e.target.value)} type="number" placeholder="أدخل المبلغ" className="mt-2 w-full rounded-2xl border border-[#e1e4ea] bg-[#f7f8fb] p-4 outline-none focus:border-[#3478db]"/><label className="mt-4 block text-sm font-bold">طريقة الاستلام</label><select value={method} onChange={e => setMethod(e.target.value)} className="mt-2 w-full rounded-2xl border border-[#e1e4ea] bg-[#f7f8fb] p-4"><option>Vodafone Cash</option><option>Etisalat Cash</option><option>Orange Cash</option><option>InstaPay</option></select><input value={destination} onChange={e => setDestination(e.target.value)} placeholder="رقم Wallet أو الحساب" className="mt-4 w-full rounded-2xl border border-[#e1e4ea] bg-[#f7f8fb] p-4 outline-none"/><button onClick={() => { const value = Number(amount); if (!value || !destination.trim()) return notify("أكمل المبلغ وبيانات الاستلام"); if (value > balance) return notify("تأكد من المبلغ المتاح"); setBalance(balance - value); notify("تم إرسال طلب السحب"); close() }} className="mt-5 w-full rounded-2xl bg-[#ef3941] py-4 font-black text-white">Confirm السحب</button></div></div></section></main> }

const QUIZES = [
  { id: "flags", title: "لعبة الأعلام", subtitle: "20 علمًا حول العالم", questions: 20, entry: 500, prize: 1500, color: "emerald", icon: "🌍", items: [{ q: "ما الدولة التي يظهر علمها بورقة الأرز؟", a: ["لبنان", "كندا", "اليابان", "الهند"], correct: "لبنان" }, { q: "ما ألوان علم فرنسا؟", a: ["أزرق وأبيض وأحمر", "أخضر وأبيض", "أحمر وأسود", "أ��فر وأزرق"], correct: "أزرق وأبيض وأحمر" }, { q: "أي علم يحتوي على نجمة وحيدة؟", a: ["تركيا", "البرازيل", "المغرب", "أسترالي��"], correct: "المغرب" }] },
  { id: "history", title: "تحدي التاريخ", subtitle: "20 سؤالًا تاريخيًا", questions: 20, entry: 500, prize: 1500, color: "purple", icon: "🏛", items: [{ q: "من بنى الأهرامات؟", a: ["المصريون القدماء", "الرومان", "الإغريق", "الفرس"], correct: "المصريون القدماء" }, { q: "في أي عام بدأت الحرب العالمية الثا��ية؟", a: ["1939", "1914", "1945", "1929"], correct: "1939" }, { q: "من أول الخلفاء الرا����دين؟", a: ["أبو بكر الصديق", "عمر بن الخطاب", "عثمان بن عفان", "���لي بن أبي طالب"], correct: "أبو بكر الصديق" }] },
  { id: "films", title: "أفلام الزمن الجميل", subtitle: "10 أسئلة سينمائية ��عبة", questions: 10, entry: 500, prize: 1500, color: "rose", icon: "🎬", items: [{ q: "من أخرج فيلم الأرض؟", a: ["يوسف شاهين", "صلاح أبو سيف", "عاطف الطيب", "حسن الإمام"], correct: "يوسف شاهين" }, { q: "من قام ببطولة فيلم شيء من الخوف؟", a: ["محمود مرسي", "أحمد زكي", "عادل إمام", "فريد شوقي"], correct: "محمود مرسي" }, { q: "ما اسم فيلم فاتن حمامة مع عمر الشريف؟", a: ["صراع في الميناء", "دعاء الكروان", "الحرام", "أريد حلا"], correct: "صراع في الميناء" }] },
]

function GameScreen({ balance, setBalance, close, notify }: { balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void }) { const [started, setStarted] = useState(false); const [selected, setSelected] = useState(0); const [questionIndex, setQuestionIndex] = useState(0); const [seconds, setSeconds] = useState(10); const [score, setScore] = useState(0); const quiz = QUIZES[selected]; const question = quiz.items[questionIndex % quiz.items.length]; const startQuiz = (index: number) => { setSelected(index); setQuestionIndex(0); setSeconds(10); setScore(0); setStarted(true) }; useEffect(() => { if (!started) return; const timer = window.setInterval(() => setSeconds((value) => { if (value <= 1) { setQuestionIndex((value) => (value + 1) % quiz.questions); setSeconds(10); notify("انتهى الوقت"); return 10 } return value - 1 }), 1000); return () => window.clearInterval(timer) }, [started, quiz.questions, notify]); return <main dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#080809] text-white"><section className="mx-auto min-h-full w-full max-w-[520px] pb-8"><header className="flex items-center justify-between border-b border-white/[.08] px-5 py-5"><button onClick={close} aria-label="إغلاق اللعبة" className="text-4xl text-white/55">×</button><h1 className="text-3xl font-black">العب واكسب</h1><span className="rounded-full bg-[#291f0c] px-4 py-2 text-[#ffc21c]">{balance} عملة</span></header>{!started ? <div className="p-5"><div className="mb-4 grid grid-cols-3 gap-2">{QUIZES.map((item, index) => <button key={item.id} onClick={() => startQuiz(index)} aria-label={`Start ${item.title} quiz`} className={`rounded-2xl border p-3 text-right ${selected === index ? "border-[#ff9d18] bg-[#33200c]" : "border-white/10 bg-[#151516]"}`}><span className="text-2xl">{item.icon}</span><b className="mt-2 block text-sm">{item.title}</b><small className="text-white/45">{item.questions} سؤال</small></button>)}</div><div className="mt-5 rounded-[32px] bg-gradient-to-br from-[#ffb01b] to-[#ff7411] p-7"><Trophy className="size-16 text-white"/><h2 className="mt-8 text-4xl font-black">{quiz.title}</h2><p className="mt-3 text-xl">{quiz.questions} سؤال · 10 ثوانٍ لكل سؤال</p><div className="mt-8 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-white/20 p-4"><p>الجائزة</p><b className="text-3xl">{quiz.prize}</b></div><div className="rounded-2xl bg-black/15 p-4"><p>الرسوم</p><b className="text-3xl">{quiz.entry}</b></div></div></div><button onClick={() => { if (balance < quiz.entry) return notify(`تحتاج إلى ${quiz.entry} عملة للعب`); setBalance(balance - quiz.entry); setStarted(true) }} className="mt-6 w-full rounded-2xl bg-[#20ca5d] py-4 text-lg font-black text-black">ابدأ اللعب الآن</button><button onClick={close} className="mt-3 w-full rounded-2xl border border-white/10 py-4 font-bold text-white/60">العودة</button></div> : <div className="p-5"><div className="flex items-center justify-between text-white/50"><span>السؤال {questionIndex + 1} من {quiz.questions}</span><span className="text-[#ffc21c]">00:{String(seconds).padStart(2, "0")}</span></div><div className="mt-5 rounded-3xl bg-[#151516] p-6"><h2 className="text-2xl font-black">{question.q}</h2><div className="mt-7 flex flex-col gap-3">{question.a.map(answer => <button key={answer} onClick={() => { notify(answer === "القاهرة" ? "إجابة صحيحة" : "إجابة غير صحيحة"); close() }} className="rounded-2xl border border-white/10 bg-[#202022] p-4 text-right font-bold hover:border-[#ffb31c]">{answer}</button>)}</div></div></div>}</section></main> }

function MethodLogo({ mark, name }: { mark: string; name: string }) {
  if (mark === "orange") return <svg role="img" aria-label={name} viewBox="0 0 64 64" className="size-[72px]"><path d="M8 26 L26 8 M10 8 H28 V26" fill="none" stroke="#111" strokeWidth="6" strokeLinejoin="miter" /><path d="M56 22 L38 40 M54 40 H36 V22" fill="none" stroke="#ff7900" strokeWidth="6" strokeLinejoin="miter" /><text x="32" y="53" textAnchor="middle" fontSize="12" fontWeight="800" fill="#111">اورنج</text><text x="32" y="64" textAnchor="middle" fontSize="12" fontWeight="800" fill="#111">كاش</text></svg>;
  if (mark === "instapay") return <span role="img" aria-label={name} className="flex flex-col items-center leading-none text-[#5a2d8c]"><span className="text-3xl font-black italic tracking-tighter">i&raquo;P</span><span className="mt-1 text-[10px] font-extrabold italic tracking-wide">INSTAPAY</span></span>;
  if (mark === "axispay") return <span role="img" aria-label={name} className="flex items-center gap-1 text-[#17c3a0]"><span className="size-3 rounded-[3px] bg-[#17c3a0]" /><span className="text-3xl font-black tracking-tight">axis</span></span>;
  if (mark === "wepay") return <span role="img" aria-label={name} className="flex flex-col items-center leading-none"><span className="text-4xl font-black italic tracking-tighter text-[#6b3a8c]">we</span><span className="mt-1 -skew-x-12 rounded-sm bg-[#6b3a8c] px-2 py-0.5 text-sm font-black italic text-white">Pay</span></span>;
  if (mark === "bm") return <span role="img" aria-label={name} className="flex size-[88px] flex-col items-center justify-center rounded-2xl bg-[#8a1c3c] leading-none text-white"><span className="text-3xl font-black tracking-tighter">BM</span><span className="mt-1 text-[10px] font-bold tracking-wide">WALLET</span></span>;
  if (mark === "smart") return <span role="img" aria-label={name} className="flex flex-col items-center leading-none text-[#1f6fb8]"><span className="mb-1 h-3 w-9 rounded-full bg-gradient-to-l from-[#f28c28] to-[#1f6fb8]" /><span className="text-xl font-black">Smart</span><span className="text-base font-medium">Wallet</span></span>;
  return <span className="text-center text-xl font-black text-[#273043]">{name}</span>;
}

function DepositScreen({ balance, setBalance, close, notify }: { balance: number; setBalance: (n: number) => void; close: () => void; notify: (m: string) => void }) { const [pick, setPick] = useState<ForeignMethod | null>(null); const [egy, setEgy] = useState<string | null>(null); const [region, setRegion] = useState<"egypt" | "crypto" | "global">("egypt"); const [picker, setPicker] = useState(false); const globalSlugs = ["paypal", "skrill-badge", "visa", "mastercard", "neteller"]; const regions = [{ id: "egypt" as const, title: "Egypt", sub: "مصر - الج��يه المصري (محافظ وانست��با��)", flag: "🇪🇬" }, { id: "crypto" as const, title: "Crypto", sub: "عملات رقمية - USDT, Bitcoin, Binance وغيرها", flag: "🪙" }, { id: "global" as const, title: "International", sub: "دولي - PayPal, Skrill, Visa, Mastercard", flag: "🌍" }]; const currentRegion = regions.find((r) => r.id === region)!; const methods = [{ name: "Vodafone Cash", mark: "vodafone", badge: "الأشهر" }, { name: "Etisalat Cash", mark: "etisalat" }, { name: "Instapay", mark: "instapay" }, { name: "Orange Cash", mark: "orange" }, { name: "Axispay", mark: "axispay", badge: "جديد" }, { name: "We Pay", mark: "wepay" }, { name: "BM Wallet", mark: "bm" }, { name: "CIB Smart Wallet", mark: "smart" }]; const icon = (slug: string) => `https://cdn.jsdelivr.net/gh/glincker/thesvg@main/public/icons/${slug}/default.svg`; const foreign = [{ name: "Binance", slug: "binance", badge: "الأشهر" }, { name: "USDT (Tether)", slug: "tether" }, { name: "Bitcoin", slug: "bitcoin" }, { name: "Ethereum", slug: "ethereum" }, { name: "BNB Chain", slug: "bnb-chain" }, { name: "Tron (TRX)", slug: "tron" }, { name: "Litecoin", slug: "litecoin" }, { name: "Solana", slug: "solana" }, { name: "Dogecoin", slug: "dogecoin" }, { name: "Coinbase", slug: "coinbase" }, { name: "OKX", slug: "okx" }, { name: "Bybit", slug: "bybit" }, { name: "PayPal", slug: "paypal" }, { name: "Skrill", slug: "skrill-badge" }, { name: "Visa", slug: "visa" }, { name: "Mastercard", slug: "mastercard" }, { name: "Neteller", slug: "neteller", src: "/payment/neteller.png" }]; const methodImage = (method: { name: string; mark: string }) => method.mark === "vodafone" ? <img src="https://cdn.jsdelivr.net/gh/glincker/thesvg@main/public/icons/vodafone/default.svg" alt="Vodafone Cash" className="size-20 object-contain" /> : method.mark === "etisalat" ? <img src="https://cdn.jsdelivr.net/gh/glincker/thesvg@main/public/icons/etisalat/default.svg" alt="Etisalat Cash" className="size-20 object-contain" /> : <MethodLogo mark={method.mark} name={method.name} />; const egyMethod = methods.find((m) => m.name === egy); if (egyMethod) return <EgyptDeposit key={egyMethod.name} name={egyMethod.name} logo={methodImage(egyMethod)} nav={<DepositNav />} close={close} back={() => setEgy(null)} notify={notify} />; if (pick) return <ForeignDeposit method={pick} close={close} back={() => setPick(null)} notify={notify} />; return <div dir="ltr" className="fixed inset-0 z-40 overflow-y-auto bg-[#f7f8fb] text-[#172033]"><div className="mx-auto min-h-full w-full max-w-[520px] pb-28"><header className="sticky top-0 z-10 flex h-[122px] items-end justify-between border-b border-[#e1e4ea] bg-white px-5 pb-5"><button onClick={close} aria-label="إغلاق الإيداع" className="text-5xl font-light leading-none text-[#6d7582]">×</button><h1 className="text-4xl font-black">إيداع</h1><button onClick={() => notify("تواصل معنا عبر الاستفسارات")} className="rounded-full bg-[#eef4ff] px-5 py-3 text-xl font-bold text-[#3478db]">استفسارات <span className="text-2xl">◯</span></button></header><div className="flex items-center justify-between bg-white px-8 py-8"><span className="text-3xl">{currentRegion.flag}</span><p className="text-2xl"><span className="font-medium">{currentRegion.title}</span> <span className="text-[#697181]">طرق الد��ع</span></p><button onClick={() => setPicker(true)} className="text-2xl font-bold text-[#3478db]">تغيير</button></div>{region === "egypt" && <section className="grid grid-cols-2 gap-7 px-5 py-8">{methods.map((method) => <button key={method.name} onClick={() => setEgy(method.name)} className={`relative flex min-h-[248px] flex-col items-center justify-center rounded-[34px] border-2 border-[#e2e4e8] bg-[#f1f2f4] px-3 shadow-sm ${method.badge ? "border-[#ff8b27]" : ""}`}>{method.badge && <span className="absolute inset-x-0 top-0 rounded-t-[31px] bg-gradient-to-l from-[#f83f4d] to-[#ff7614] py-2 text-center text-xl font-black text-white">{method.badge}</span>}<span className="mb-7 flex size-28 items-center justify-center rounded-3xl bg-white shadow-sm">{methodImage(method)}</span><span className="text-2xl font-medium">{method.name}</span></button>)}</section>}{region !== "egypt" && <section className="grid grid-cols-2 gap-7 px-5 py-8">{foreign.filter((m) => region === "global" ? globalSlugs.includes(m.slug) : !globalSlugs.includes(m.slug)).map((method) => <button key={method.name} onClick={() => setPick(method)} className={`relative flex min-h-[248px] flex-col items-center justify-center rounded-[34px] border-2 border-[#e2e4e8] bg-[#f1f2f4] px-3 shadow-sm ${method.badge ? "border-[#ff8b27]" : ""}`}>{method.badge && <span className="absolute inset-x-0 top-0 rounded-t-[31px] bg-gradient-to-l from-[#f83f4d] to-[#ff7614] py-2 text-center text-xl font-black text-white">{method.badge}</span>}<span className="mb-7 flex size-28 items-center justify-center rounded-3xl bg-white shadow-sm"><img src={method.src ?? icon(method.slug)} alt={method.name} className="size-20 rounded-2xl object-contain" /></span><span className="text-2xl font-medium">{method.name}</span></button>)}</section>}</div>{picker && <div className="fixed inset-0 z-[60] flex items-end justify-center bg-black/50" onClick={() => setPicker(false)}><div role="dialog" aria-label="تغيير طرق الدفع" onClick={(e) => e.stopPropagation()} className="w-full max-w-[520px] rounded-t-[34px] bg-white px-5 pb-10 pt-6"><div className="mb-5 flex items-center justify-between"><h2 className="text-3xl font-black">اختر العملة / الدولة</h2><button onClick={() => setPicker(false)} aria-label="إغلاق" className="text-4xl font-light leading-none text-[#6d7582]">×</button></div><div className="flex flex-col gap-3">{regions.map((r) => <button key={r.id} onClick={() => { setRegion(r.id); setPicker(false) }} className={`flex items-center gap-4 rounded-3xl border-2 px-5 py-4 text-right ${region === r.id ? "border-[#ff8b27] bg-[#fff6ee]" : "border-[#e2e4e8] bg-[#f1f2f4]"}`}><span className="flex size-14 items-center justify-center rounded-2xl bg-white text-3xl shadow-sm">{r.flag}</span><span className="flex-1"><span className="block text-2xl font-bold">{r.title}</span><span className="block text-lg text-[#697181]">{r.sub}</span></span>{region === r.id && <span className="text-2xl font-black text-[#20ca5d]">✓</span>}</button>)}</div></div></div>}<DepositNav /></div> }

function DepositNav() { return <nav className="fixed bottom-0 left-1/2 z-50 flex w-full max-w-[520px] -translate-x-1/2 justify-between border-t border-[#25262a] bg-[#171719] px-2 py-3 text-[#a0a1aa]"><span className="flex flex-1 flex-col items-center gap-1 text-xs"><User className="size-7"/>My Account</span><span className="flex flex-1 flex-col items-center gap-1 rounded-2xl bg-[#063b27] py-2 text-xs text-[#20ca5d]"><Wallet className="size-7"/>Wallet</span><span className="flex flex-1 flex-col items-center gap-1 text-xs"><Bell className="size-7"/>Notifications</span><span className="flex flex-1 flex-col items-center gap-1 text-xs"><Trophy className="size-7"/>Competitions</span><span className="flex flex-1 flex-col items-center gap-1 text-xs"><ReceiptText className="size-7"/>Finance و النسخ</span><span className="flex flex-1 flex-col items-center gap-1 text-xs"><Home className="size-7"/>Home</span></nav> }

function Forgot({ setScreen }: { setScreen: (s: Screen) => void }) { return <main dir="ltr" className="min-h-screen bg-[#080809] text-white"><section className="mx-auto flex min-h-screen w-full max-w-[520px] flex-col px-6 py-8"><button onClick={() => setScreen("language")} className="self-start rounded-full border border-white/10 px-4 py-2 text-white/60">Back</button><div className="mt-24 rounded-[28px] border border-white/[.07] bg-[#151516] p-6 text-center"><h1 className="text-3xl font-black">استعادة Password</h1><p className="mt-3 text-white/45">أدخل رقم الهاتف أو البريد لإرسال رمز التحقق</p><input aria-label="رقم الهاتف أو Email" placeholder="رقم الهاتف أو Email" className="mt-8 w-full rounded-2xl border border-white/10 bg-[#0b0b0c] p-4 outline-none focus:border-[#ff9d18]"/><button onClick={() => setScreen("verify")} className="mt-4 w-full rounded-2xl bg-[#ff9d18] py-4 font-black text-black">إرسال رمز التح��ق</button></div></section></main> }
